    'Monthly/fixed-contract staff get their full rate. Weekly = rate × present-weeks (6 working days/week). Daily = days × rate. Hourly = hours × rate (attendance captures hours). Overtime = hours beyond 8/day at 1.5× (or the employee\'s OT rate). Advances deduct automatically from this salary (full outstanding, or the employee\'s monthly deduction cap). Due loan installments due in the period deduct automatically. Loans never touch advance accounting. Nothing posts until Owner/Admin approves each payment.' => 'Monthly/fixed-contract staff get their full rate. Weekly = rate × present-weeks (6 working days/week). Daily = days × rate. Hourly = hours × rate (attendance captures hours). Overtime = hours beyond 8/day at 1.5× (or the employee\'s OT rate). Advances deduct automatically from this salary (full outstanding, or the employee\'s monthly deduction cap). Due loan installments due in the period deduct automatically. Loans never touch advance accounting. Nothing posts until Owner/Admin approves each payment.',
