    'Monthly/fixed-contract staff get their full rate. Weekly = rate × present-weeks (6 working days/week). Daily = days × rate. Hourly = hours × rate (attendance captures hours). Overtime = hours beyond 8/day at 1.5× (or the employee\'s OT rate). Advances deduct automatically from this salary (full outstanding, or the employee\'s monthly deduction cap). Due loan installments due in the period deduct automatically. Loans never touch advance accounting. Nothing posts until Owner/Admin approves each payment.' => 'ماہانہ/فکسڈ کنٹریکٹ ملازمین کو مکمل ریٹ ملتا ہے۔ ہفتہ وار = ریٹ × موجودہ ہفتے (ہفتے میں 6 کام کے دن)۔ روزانہ = دن × ریٹ۔ گھنٹے = گھنٹے × ریٹ (حاضری گھنٹے پکڑتی ہے)۔ اوور ٹائم = 8 گھنٹے/دن سے زائد پر 1.5× (یا ملازم کا OT ریٹ)۔ پیشگیاں اس تنخواہ سے خود بخود منہا ہوتی ہیں (پوری بقایا، یا ملازم کی ماہانہ کٹوتی کی حد)۔ واجب قرض قسطیں دورانیہ میں خود بخود منہا ہوتی ہیں۔ قرض کبھی پیشگی اکاؤنٹ سے نہیں جڑتے۔ جب تک مالک/ایڈمن ہر ادائیگی منظور نہ کرے، کچھ پوسٹ نہیں ہوتا۔',
