    'This account is not allowed to sign in. This ERP is for the Owner/Admin, Manager and Accountant only.' => 'اس اکاؤنٹ کو سائن ان کرنے کی اجازت نہیں ہے۔ یہ ERP صرف مالک/ایڈمن، مینیجر اور اکاؤنٹنٹ کے لیے ہے۔',
    'This advance will be adjusted against upcoming salary / commission. The salesman authorises this deduction with their signature below.' => 'یہ ایڈوانس آئندہ تنخواہ / کمیشن سے منہا ہو گا۔ سیلز مین نیچے دستخط کر کے اس کٹائوتی کی منظوری دیتا ہے/دیتی ہے۔',
    'This advance will be adjusted against upcoming salary. The employee authorises this deduction with their signature below.' => 'یہ ایڈوانس آئندہ تنخواہ سے منہا ہو گا۔ ملازم نیچے دستخط کر کے اس کٹائوتی کی منظوری دیتا ہے/دیتی ہے۔',
    'This cannot be undone from the UI (you would need to reverse the CL entries manually).' => 'اسے UI سے واپس نہیں کیا جا سکتا (CL اندراجات دستی طور پر ریورس کرنی پڑیں گی)۔',
