    'This claim is fully settled. ✓' => 'یہ کلیم مکمل طور پر سیٹل ہو گیا۔ ✓',
    'This company is configured with a single Main Warehouse. Add another warehouse only for exceptional management reasons — it is not needed for normal operations.' => 'یہ کمپنی ایک واحد مین گودام کے ساتھ کنفیگرڈ ہے۔ دوسرا گودام صرف غیر معمولی مینجمنٹ وجوہات کی بنا پر شامل کریں — نارمل آپریشنز کے لیے ضروری نہیں۔',
    'This company is configured with a single Main Warehouse. Add another warehouse only for exceptional management reasons. Continue?' => 'یہ کمپنی ایک واحد مین گودام کے ساتھ کنفیگرڈ ہے۔ دوسرا گودام صرف غیر معمولی مینجمنٹ وجوہات کی بنا پر شامل کریں۔ جاری رکھیں؟',
    'This document will be posted to the system. This action cannot be undone.' => 'یہ دستاویز سسٹم میں پوسٹ ہو جائے گی۔ یہ عمل واپس نہیں کیا جا سکتا۔',
    'This form was already submitted. Loading the existing invoice.' => 'یہ فارم پہلے ہی جمع ہو چکا ہے۔ موجودہ انوائس لوڈ ہو رہی ہے۔',
    'This installation uses one Main Warehouse only. All stock (production, purchases, opening stock, counts and reports) and goods issues to salesmen flow through it. Salesman vans remain separate salesman stock locations. Additional warehouses are not part of the normal workflow — use Settings → Warehouses (Owner/Admin) only for exceptional system management.' => 'اس انسٹالیشن میں صرف ایک مین گودام ہے۔ تمام اسٹاک (پروڈکشن، خریداری، اوپننگ اسٹاک، گنتی اور رپورٹس) اور سیلز مین کو مال دینا اسی گودام سے ہوتا ہے۔ سیلز مین کی وین ان کے الگ اسٹاک لوکیشن رہتے ہیں۔ مزید گودام نارمل ورک فلو کا حصہ نہیں — Settings → Warehouses (صرف مالک/ایڈمن) صرف غیر معمولی سسٹم مینجمنٹ کے لیے استعمال کریں۔',
    'This month' => 'اس مہینے',
    'This month:' => 'اس مہینے:',
    'This payslip is already fully paid.' => 'یہ پے سلپ پہلے ہی پوری ادا ہو چکی ہے۔',
    'This period already contains payslips — generating again will skip employees who already have one. Reverse a payslip to re-generate it.' => 'اس مدت کی تنخواہیں پہلے سے موجود ہیں — دوبارہ جنریٹ کرنے پر پہلے سے بن چکے ملازمین کو چھوڑ دیا جائے گا۔ ریورس کر کے دوبارہ بنائیں۔',
    'This request is awaiting Owner/Admin approval. You will be notified the moment a decision is made.' => 'یہ درخواست Owner/Admin کی منظوری کا انتظار کر رہی ہے۔ فیصلہ ہوتے ہی آپ کو مطلع کیا جائے گا۔',
    'This request is pending approval. Only Owner/Admin can approve or reject it — Managers cannot decide approvals. You will be notified when a decision is made.' => 'یہ درخواست منظوری کی متنظر ہے۔ منظور/مسترد صرف مالک یا ایڈمن کر سکتے ہیں — مینیجر فیصلے نہیں کر سکتے۔ فیصلہ ہونے پر آپ کو اطلاع دی جائے گی۔',
