    'Monthly summary' => 'Monthly khulasa',
    'Monthly/fixed-contract staff get their full rate. Weekly = rate × present-weeks (6 working days/week). Daily = days × rate. Hourly = hours × rate (attendance captures hours). Overtime = hours beyond 8/day at 1.5× (or the employee\'s OT rate). Advances deduct automatically from this salary (full outstanding, or the employee\'s monthly deduction cap). Due loan installments due in the period deduct automatically. Loans never touch advance accounting. Nothing posts until Owner/Admin approves each payment.' => 'Mahana/fixed-contract mulazmin ko poora rate milta hai. Weekly = rate × present-weeks (week mein 6 kaam ke din). Daily = din × rate. Hourly = ghantay × rate (hazri ghantay capture karti hai). Overtime = 8 ghante/din se zyada par 1.5× (ya mulazim ka OT rate). Advances is salary se khud-ba-khud katoti hoti hain (poori baqaya, ya mulazim ki monthly deduction cap). Due qarz qistain period mein khud-ba-khud katoti hain. Qarz kabhi advance account se nahi jate. Jab tak Owner/Admin har adaigi approve na kare, kuch post nahi hota.',
