    'This claim is fully settled. ✓' => 'Ye claim fully settled hai. ✓',
    'This company is configured with a single Main Warehouse. Add another warehouse only for exceptional management reasons — it is not needed for normal operations.' => 'Ye company ek wahid Main Warehouse ke sath configured hai. Dusra warehouse sirf khas management wajah par add karein — normal operations ke liye zaroorat nahi.',
    'This company is configured with a single Main Warehouse. Add another warehouse only for exceptional management reasons. Continue?' => 'Ye company ek wahid Main Warehouse ke sath configured hai. Dusra warehouse sirf khas management wajah par add karein. Continue?',
    'This document will be posted to the system. This action cannot be undone.' => 'Yeh dastavez system mein post ho jayegi. Yeh amal wapas nahi kiya ja sakta.',
    'This form was already submitted. Loading the existing invoice.' => 'Ye form pehle hi submit ho chuka hai. Existing invoice load ho rahi hai.',
    'This installation uses one Main Warehouse only. All stock (production, purchases, opening stock, counts and reports) and goods issues to salesmen flow through it. Salesman vans remain separate salesman stock locations. Additional warehouses are not part of the normal workflow — use Settings → Warehouses (Owner/Admin) only for exceptional system management.' => 'Is installation mein sirf ek Main Warehouse hai. Tamam stock (production, purchases, opening stock, counts aur reports) aur salesman ko goods issue issi warehouse se hota hai. Salesman vans alag stock locations rehte hain. Naye warehouses normal workflow ka hissa nahi — Settings → Warehouses (Owner/Admin) sirf khas system management ke liye istemal karein.',
    'This month' => 'Is mahine',
    'This month:' => 'Is mahine:',
    'This payslip is already fully paid.' => 'Yeh payslip pehle hi poori ada ho chuki hai.',
    'This period already contains payslips — generating again will skip employees who already have one. Reverse a payslip to re-generate it.' => 'Is period ki payslips pehle se mojood hain — dubara generate karne par pehle se payslip wale employees skip ho jayenge. Reverse karke dubara banain.',
    'This request is awaiting Owner/Admin approval. You will be notified the moment a decision is made.' => 'Yeh request Owner/Admin ki approval ke intezar mein hai. Decision hote hi aap ko notify kiya jayega.',
    'This request is pending approval. Only Owner/Admin can approve or reject it — Managers cannot decide approvals. You will be notified when a decision is made.' => 'Yeh request abhi manzoor hone ki raah dekh rahi hai. Approve/reject sirf Owner/Admin kar sakte hain — Manager approve nahi kar sakte. Faisla hone par aap ko notify kiya jaye ga.',
    'This system keeps a running record of role changes in Salary History (Set Salary with effective date).' => 'Yeh system Salary History (effective date ke sath Set Salary) mein role changes ka record rakhta hai.',
